local StagePropMaker = {}
local PRODUCTS = {
    simple_wooden_prop = { name = "Preprost lesen rekvizit", woodCost = 2, paintCost = 1, time = 3, cost = 40, artistry = 18, happiness = 2, description = "Preprost lesen rekvizit za gledališče." },
    painted_scenery_flat = { name = "Poslikana kulisa", woodCost = 2, paintCost = 2, linenCost = 1, time = 6, cost = 130, artistry = 35, happiness = 2, prestige = 2, description = "Poslikana kulisa za trgovce." },
    gilded_throne_prop = { name = "Pozlačeni prestol rekvizit", woodCost = 3, paintCost = 2, goldCost = 1, silverCost = 1, linenCost = 1, time = 10, cost = 320, artistry = 50, happiness = 3, prestige = 6, description = "Pozlačeni prestol rekvizit za plemiče." },
    silver_decorated_set = { name = "Srebrnookrašena oprema", woodCost = 3, paintCost = 2, silverCost = 2, goldCost = 1, linenCost = 1, time = 14, cost = 760, artistry = 65, happiness = 4, prestige = 14, description = "Srebrnookrašena oprema za visoke plemiče." },
    jewel_inlaid_prop = { name = "Draguljarski rekvizit", woodCost = 3, paintCost = 2, goldCost = 2, silverCost = 1, jewelCost = 1, linenCost = 1, time = 18, cost = 1700, artistry = 78, happiness = 6, prestige = 27, description = "Rekvizit z draguljem za visoko plemstvo." },
    royal_grand_stage_set = { name = "Kraljevski veliki gledališka oprema", woodCost = 5, paintCost = 4, goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 2, linenCost = 2, time = 25, cost = 3900, artistry = 92, happiness = 12, prestige = 58, description = "Velika kraljevska gledališka oprema z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    prop_workshop = { name = "Rekvizitna delavnica", cost = { gold = 220, wood = 120, stone = 100, paint = 6 }, upkeep = 5, qualityBonus = 5 },
    scenery_loft = { name = "Kulisna podstrešje", cost = { gold = 820, wood = 260, stone = 240, silver = 6, linen = 6 }, upkeep = 19, qualityBonus = 18 },
    master_prop_atelier = { name = "Mojstrski rekvizitni atelje", cost = { gold = 2400, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 55, qualityBonus = 30 },
    royal_theater_palace = { name = "Kraljevska gledališka palača", cost = { gold = 9800, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 195, qualityBonus = 55, prestigeBonus = 50 },
}
StagePropMaker.woodStock = 16; StagePropMaker.paintStock = 14; StagePropMaker.linenStock = 10; StagePropMaker.silverStock = 6; StagePropMaker.goldStock = 6; StagePropMaker.jewelStock = 4; StagePropMaker.pearlStock = 4
StagePropMaker.productStock = {}; StagePropMaker.buildings = {}; StagePropMaker.maker = nil; StagePropMaker.activeMaking = {}; StagePropMaker.totalProducts = 0; StagePropMaker.dayTimer = 0
function StagePropMaker.init() StagePropMaker.woodStock=16; StagePropMaker.paintStock=14; StagePropMaker.linenStock=10; StagePropMaker.silverStock=6; StagePropMaker.goldStock=6; StagePropMaker.jewelStock=4; StagePropMaker.pearlStock=4; StagePropMaker.productStock={}; StagePropMaker.buildings={}; StagePropMaker.maker=nil; StagePropMaker.activeMaking={}; StagePropMaker.totalProducts=0; StagePropMaker.dayTimer=0; print("[StagePropMaker] Royal Stage Prop Maker System initialized (6 products, 4 buildings)") end
function StagePropMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; StagePropMaker.maker={name=n or ("Rekvizitar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rekvizitar najet: %s (spretnost: %d)",StagePropMaker.maker.name,s),"success") end; return true end
function StagePropMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function StagePropMaker.build(id) local ok,e=StagePropMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(StagePropMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function StagePropMaker.getQualityBonus() local b=0; for _,bd in ipairs(StagePropMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function StagePropMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and StagePropMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.paintCost and StagePropMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.linenCost and StagePropMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.silverCost and StagePropMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and StagePropMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and StagePropMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and StagePropMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #StagePropMaker.buildings==0 then return false,"Potrebna rekvizitna delavnica" end; if not StagePropMaker.maker then return false,"Potreben rekvizitar" end; return true end
function StagePropMaker.make(pt,qty) qty=qty or 1; local ok,e=StagePropMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then StagePropMaker.woodStock=StagePropMaker.woodStock-d.woodCost*qty end; if d.paintCost then StagePropMaker.paintStock=StagePropMaker.paintStock-d.paintCost*qty end; if d.linenCost then StagePropMaker.linenStock=StagePropMaker.linenStock-d.linenCost*qty end; if d.silverCost then StagePropMaker.silverStock=StagePropMaker.silverStock-d.silverCost*qty end; if d.goldCost then StagePropMaker.goldStock=StagePropMaker.goldStock-d.goldCost*qty end; if d.jewelCost then StagePropMaker.jewelStock=StagePropMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then StagePropMaker.pearlStock=StagePropMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if StagePropMaker.maker then t=math.max(1,t-math.floor(StagePropMaker.maker.skill/13)) end; table.insert(StagePropMaker.activeMaking,{id="stageprop_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,artistry=d.artistry or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function StagePropMaker.completeMaking(m) local q=1.0+(StagePropMaker.getQualityBonus()/100); if StagePropMaker.maker then q=q+(StagePropMaker.maker.skill/150) end; q=math.min(2.4,q); StagePropMaker.productStock[m.productType]=(StagePropMaker.productStock[m.productType] or 0)+m.quantity; StagePropMaker.totalProducts=StagePropMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if StagePropMaker.maker then StagePropMaker.maker.itemsMade=StagePropMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then StagePropMaker.maker.skill=math.min(100,StagePropMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rekvizit izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"stageprop.completed",{productName=m.productName,artistry=m.artistry,prestige=m.prestige,happiness=m.happiness}) end end
function StagePropMaker.update(dt) if not _G.state then return end; StagePropMaker.dayTimer=StagePropMaker.dayTimer+dt; if StagePropMaker.dayTimer>=30 then StagePropMaker.dayTimer=0; for i=#StagePropMaker.activeMaking,1,-1 do local m=StagePropMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then StagePropMaker.completeMaking(m); table.remove(StagePropMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(StagePropMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if StagePropMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function StagePropMaker.getStats() return {woodStock=StagePropMaker.woodStock,paintStock=StagePropMaker.paintStock,linenStock=StagePropMaker.linenStock,silverStock=StagePropMaker.silverStock,goldStock=StagePropMaker.goldStock,jewelStock=StagePropMaker.jewelStock,pearlStock=StagePropMaker.pearlStock,productStock=StagePropMaker.productStock,numBuildings=#StagePropMaker.buildings,hasMaker=StagePropMaker.maker~=nil,makerName=StagePropMaker.maker and StagePropMaker.maker.name or "—",makerSkill=StagePropMaker.maker and StagePropMaker.maker.skill or 0,activeMaking=#StagePropMaker.activeMaking,totalProducts=StagePropMaker.totalProducts} end
return StagePropMaker
